mapper.select:
SELECT h.id AS homeworkId, h.homework_name AS workName, ROUND(AVG(hr.score), 1) AS avgScore, MAX(hr.score) AS maxScore, MIN(hr.score) AS minScore FROM edu_homework h JOIN edu_homework_record hr ON h.id = hr.homework_id AND hr.deleted = 0 AND hr.status = 2 WHERE h.deleted = 0 AND h.status IN (1, 2, 3) AND h.course_id = #{courseId}
AND h.class_id = #{classId}
GROUP BY h.id, h.homework_name, h.create_time ORDER BY h.create_time ASC

SELECT DISTINCT ec.id AS id, ec.class_name AS name FROM edu_class_course ecc JOIN edu_class ec ON ecc.class_id = ec.id AND ec.deleted = 0 JOIN capacity_course cc ON ecc.course_id = cc.id AND cc.deleted = 0 WHERE ecc.deleted = 0 AND ecc.course_id = #{courseId}
AND ((cc.is_public_course = 0 AND (cc.teacher_Id = #{teacherId} OR (ecc.status = 0 AND ecc.claim_teacher_id = #{teacherId}))) OR ((cc.is_public_course IS NULL OR cc.is_public_course != 0) AND (cc.teacher_Id = #{teacherId} OR EXISTS (SELECT 1 FROM capacity_course_member team WHERE team.course_id = cc.id AND team.user_id = #{teacherId} AND team.deleted = 0))))
ORDER BY ec.class_name

SELECT ec.id FROM edu_class ec JOIN system_dept d_major ON ec.dept_id = d_major.id AND d_major.deleted = 0 LEFT JOIN system_dept d_college ON d_major.parent_id = d_college.id AND d_college.deleted = 0 WHERE ec.deleted = 0
AND d_college.id = #{collegeId}
AND d_major.id = #{majorId}

SELECT h.id AS homeworkId, h.homework_name AS homeworkName, ROUND(AVG(hr.score), 1) AS avgScore FROM edu_homework h JOIN edu_homework_record hr ON h.id = hr.homework_id AND hr.deleted = 0 AND hr.status = 2 WHERE h.deleted = 0 AND h.status IN (1, 2, 3) AND h.course_id = #{courseId}
AND h.class_id = #{classId}
GROUP BY h.id, h.homework_name, h.create_time ORDER BY h.create_time ASC

SELECT ranked.homeworkId, ranked.studentId, ranked.studentName, ranked.score, ranked.topRank, ranked.lastRank FROM ( SELECT hr.homework_id AS homeworkId, hr.student_id AS studentId, su.nickname AS studentName, hr.score, ROW_NUMBER() OVER (PARTITION BY hr.homework_id ORDER BY hr.score DESC) AS topRank, ROW_NUMBER() OVER (PARTITION BY hr.homework_id ORDER BY hr.score ASC) AS lastRank
AND hr.homework_id IN #{id}
AND 1 = 0
) ranked WHERE ranked.topRank <= 5 OR ranked.lastRank <= 5

SELECT COUNT(*) FROM capacity_course c WHERE c.deleted = 0 AND c.status = 0
    AND (c.teacher_Id = #{teacherId}
        OR (c.is_public_course = 0 AND EXISTS (SELECT 1 FROM edu_class_course binding
            JOIN edu_class ec ON ec.id = binding.class_id AND ec.deleted = 0 AND ec.status = 0
            WHERE binding.course_id = c.id AND binding.claim_teacher_id = #{teacherId}
                AND binding.deleted = 0 AND binding.status = 0)))
